/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
zones=['.','com','net','example.com','service.com','lab.net','tools.net','shop.example.com','api.service.com','research.lab.net','ci.tools.net','ai.research.lab.net','data.research.lab.net']
ips={i:re.search(r\"inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/24\",Path(f'pc{i}.startup').read_text()).group(1) for i in range(1,21)}
servers={z:i+1 for i,z in enumerate(zones)}
children={'.':['com','net'],'com':['example.com','service.com'],'net':['lab.net','tools.net'],'example.com':['shop.example.com'],'service.com':['api.service.com'],'lab.net':['research.lab.net'],'tools.net':['ci.tools.net'],'research.lab.net':['ai.research.lab.net','data.research.lab.net']}
records={'shop.example.com':[('@','A',8)],'api.service.com':[('@','A',9)],'ci.tools.net':[('@','A',11)],'ai.research.lab.net':[('@','A',12)],'data.research.lab.net':[('@','A',13)]}
for z,i in [('example.com',4),('service.com',5),('lab.net',6),('tools.net',7)]: records[z]=[('mail','A',i),('@','MX',f'10 mail.{z}.')]
def ns(z): return 'a.root-servers.' if z=='.' else f'ns.{z}.'
conf=Path('lab.conf'); text=conf.read_text()
for i in range(1,15): text=text.replace(f'pc{i}[image]=\"kathara/base\"',f'pc{i}[image]=\"kathara/bind\"')
conf.write_text(text)
for z,i in servers.items():
 d=Path(f'pc{i}/etc/bind'); d.mkdir(parents=True,exist_ok=True)
 filename='db.root' if z=='.' else 'db.'+z
 (d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion no; allow-query { any; };\\n  dnssec-validation no; listen-on { any; }; listen-on-v6 { none; }; };\\n'+f'zone \"{z}\" {{ type master; file \"/etc/bind/{filename}\"; }};\\n')
 origin='.' if z=='.' else z+'.'
 hostmaster='hostmaster.' if z=='.' else f'hostmaster.{z}.'
 lines=[f'"'$ORIGIN {origin}'"','"'$TTL 3600'"',f'@ IN SOA {ns(z)} {hostmaster} ( 1 3600 900 604800 300 )',f'@ IN NS {ns(z)}',f'{ns(z)} IN A {ips[i]}']
 for owner,typ,val in records.get(z,[]): lines.append(f'{owner} IN {typ} {ips[val] if typ==\"A\" else val}')
 for child in children.get(z,[]):
  lines.append(f'{child}. IN NS {ns(child)}')
  lines.append(f'{ns(child)} IN A {ips[servers[child]]}')
 (d/filename).write_text('\\n'.join(lines)+'\\n')
for i in range(1,15):
 p=Path(f'pc{i}.startup'); p.write_text(p.read_text()+'\\nsystemctl restart named\\n')
d=Path('pc14/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion yes; allow-recursion { any; }; allow-query { any; };\\n  dnssec-validation no; listen-on { any; }; listen-on-v6 { none; }; };\\nzone \".\" { type hint; file \"/etc/bind/db.hints\"; };\\n')
(d/'db.hints').write_text(f'. 3600000 IN NS a.root-servers.\\na.root-servers. 3600000 IN A {ips[1]}\\n')
for i in range(16,21):
 p=Path(f'pc{i}.startup'); p.write_text(p.read_text()+f'\\necho \"nameserver {ips[14]}\" > /etc/resolv.conf\\n')
PY"

